from scipy.spatial.transform import Rotation as R

def current():
    m=json.loads((OUT/'latest.json').read_text()); p=m['proprio']; return m,dict(zip(p['layout'],p['now']))
def joints():
    _,p=current()
    names=['torso_joint'+str(i) for i in range(1,5)]
    names+=['left_arm_joint'+str(i) for i in range(1,8)]
    names+=['left_gripper_finger_joint1','left_gripper_finger_joint2']
    names+=['right_arm_joint'+str(i) for i in range(1,8)]
    names+=['right_gripper_finger_joint1','right_gripper_finger_joint2']
    return np.array([0,0,0]+[p[n] for n in names])
def act(A,dt=1/30,note=''):
    A=np.asarray(A).reshape(-1,25)
    with (OUT/'commands.jsonl').open('a') as f: f.write(json.dumps({'type':'joint_position','A':A.tolist(),'dt':dt,'note':note})+'\n')
    name='run%03d'%len(list(OUT.glob('run*')))
    try: res=r.submit('joint_position',A,dt=dt,depth=True,video='mp4',note=note)
    except Exception:
        print('RECOVERY',r.wait_ready()); print(r.status()); save(r.get_obs(depth=True),name+'_recovery'); raise
    return save(res,name)
def move(dx=0,dy=0,da=0,n=60):
    a=joints(); a[:3]=np.array([dx,dy,da])/n
    rows=np.tile(a,(n,1)); stop=a.copy();stop[:3]=0
    return act(np.vstack([rows,np.tile(stop,(15,1))]),note='base movement')
def point(cam,u,v):
    m,_=current(); c=list(m['cameras'])[cam] if isinstance(cam,int) else cam
    d=np.load(OUT/'latest_depth.npz')[c]; z=float(d[v,u]);cal=m['cameras'][c]
    K=np.array(cal['intrinsic_cv']); E=np.array(cal['extrinsic_cv']);xyz=np.linalg.inv(K)@np.array([u,v,1])*z
    return E[:,:3].T@(xyz-E[:,3])
PY
